<script>
export const page={name:"fulfillments",path:"/fulfillments",title:"履約工作列表",requires:{permissions:["fulfillment.view"]},menu:{group:"fulfillment",icon:"assignment",order:20}};
</script>
<script setup>
import {reactive,watch} from "vue";
import PageHeader from "@/framework/layout/PageHeader.vue";
import DataTable from "@/framework/ui/DataTable.vue";
import {useFulfillmentPage} from "@/components/fulfillment/useFulfillmentPage.js";
import {statusLabels,statusColors,timestamp} from "@/components/fulfillment/fulfillmentPresentation.js";
const {route,data,loading,error,load,apply,next,first}=useFulfillmentPage("list"),filters=reactive({view:"active",q:"",salesOrderId:"",customerId:"",warehouseId:"",status:null,hasShortPick:null,sortBy:"lastBusinessUpdatedAt",descending:true,pageSize:20,createdFrom:null,createdTo:null,pickedFrom:null,pickedTo:null});
watch(()=>route.fullPath,()=>{for(const key of Object.keys(filters))filters[key]=route.query[key]??({view:"active",sortBy:"lastBusinessUpdatedAt",descending:true,pageSize:20}[key]??null);if(["true","false"].includes(filters.descending))filters.descending=filters.descending==="true";filters.pageSize=Number(filters.pageSize);},{immediate:true});
const views=[{value:"myRecent",label:"我最近的工作"},{value:"active",label:"進行中"},{value:"exceptions",label:"例外"},{value:"finalized",label:"已完成／結束"}],columns=[{name:"number",label:"履約單",field:"number",align:"left"},{name:"sales",label:"SO",field:"salesOrderNumber",align:"left"},{name:"customer",label:"客戶",field:row=>`${row.customer.code} — ${row.customer.name}`,align:"left"},{name:"warehouse",label:"倉庫",field:row=>`${row.warehouse.code} — ${row.warehouse.name}`,align:"left"},{name:"status",label:"狀態",field:"status"},{name:"lines",label:"行數",field:"lineCount"},{name:"short",label:"短揀",field:row=>row.hasShortPick?'有短揀':'沒有短揀'},{name:"updated",label:"更新時間",field:row=>timestamp(row.updatedAt)},{name:"actions",label:"操作",field:"id",align:"right"}];
function dateValue(value){if(value===null||value===undefined)return "";const date=new Date(Number(value));return Number.isFinite(date.getTime())?new Intl.DateTimeFormat("en-CA",{timeZone:"Asia/Hong_Kong",year:"numeric",month:"2-digit",day:"2-digit"}).format(date):"";}
function setDate(key,value){filters[key]=value?Date.parse(`${value}T${key.endsWith('To')?'23:59:59.999':'00:00:00.000'}+08:00`):null;}
</script>
<template><div><PageHeader subtitle="所有狀態及可用操作以目前後端資料為準。"><template #actions><q-btn flat label="履約工作佇列" to="/fulfillment/queue" /></template></PageHeader>
 <section aria-label="履約工作內容" class="q-px-md q-pb-md" :aria-busy="loading"><q-tabs :model-value="filters.view" @update:model-value="value=>apply({...filters,view:value})"><q-tab v-for="view in views" :key="view.value" :name="view.value" :label="view.label" /></q-tabs>
  <div class="row q-col-gutter-md q-mt-sm"><div class="col-12 col-md-4"><q-input v-model="filters.q" label="履約單／SO 編號（精確）" maxlength="190" outlined dense @keyup.enter="apply(filters)" /></div><div class="col-6 col-md-2"><q-input v-model="filters.salesOrderId" label="SO ID" inputmode="numeric" outlined dense /></div><div class="col-6 col-md-2"><q-input v-model="filters.customerId" label="客戶 ID" inputmode="numeric" outlined dense /></div><div class="col-6 col-md-2"><q-input v-model="filters.warehouseId" label="倉庫 ID" inputmode="numeric" outlined dense /></div>
   <div class="col-6 col-md-2"><q-select v-model="filters.status" label="履約狀態" :options="Object.entries(statusLabels).filter(([value])=>!['CONFIRMED','PARTIALLY_FULFILLED'].includes(value)).map(([value,label])=>({value,label}))" emit-value map-options clearable outlined dense /></div>
   <div class="col-6 col-md-3"><q-select v-model="filters.hasShortPick" label="短揀" :options="[{value:'true',label:'有短揀'},{value:'false',label:'沒有短揀'}]" emit-value map-options clearable outlined dense /></div><div class="col-6 col-md-4"><q-select v-model="filters.sortBy" label="排序" :options="[{value:'lastBusinessUpdatedAt',label:'最後業務更新'},{value:'createdAt',label:'建立時間'},{value:'updatedAt',label:'更新時間'},{value:'fulfillmentNumber',label:'履約單編號'},{value:'id',label:'履約單 ID'}]" emit-value map-options outlined dense /></div><div class="col-6 col-md-3"><q-select v-model="filters.descending" label="排序方向" :options="[{value:false,label:'升序'},{value:true,label:'降序'}]" emit-value map-options outlined dense /></div><div class="col-6 col-md-2"><q-select v-model="filters.pageSize" label="每頁筆數" :options="[20,50,100]" outlined dense /></div>
   <div v-for="[key,label] in [['createdFrom','建立日期由'],['createdTo','建立日期至'],['pickedFrom','揀貨日期由'],['pickedTo','揀貨日期至']]" :key="key" class="col-6 col-md-3"><q-input :model-value="dateValue(filters[key])" type="date" :label="label+'（香港時間）'" outlined dense @update:model-value="value=>setDate(key,value)" /></div>
  </div><div class="row q-gutter-sm q-my-md"><q-btn label="搜尋" color="primary" @click="apply(filters)" /><q-btn flat label="清除篩選" @click="apply({})" /></div>
  <q-banner v-if="error" role="alert" class="bg-warning text-dark q-mb-md">{{ error }}<template #action><q-btn flat label="重新載入" @click="load" /></template></q-banner>
  <DataTable :key="route.fullPath" :rows="data.items" :columns="columns" :loading="loading" sticky-actions :initial-pagination="{page:1,rowsPerPage:100}"><template #body-cell-status="{row}"><q-td><q-badge :color="statusColors[row.status]" :label="statusLabels[row.status]" /></q-td></template><template #body-cell-actions="{row}"><q-td><q-btn flat :label="`查看 ${row.number}`" :to="`/fulfillments/${row.id}`" /></q-td></template>
   <template #no-data><p v-if="!error" role="status">沒有符合條件的履約工作，請調整篩選。</p></template><template #bottom><div class="row items-center q-gutter-sm q-pa-sm"><span>第 {{ data.page }} 頁・本頁 {{ data.items.length }} 筆</span><q-btn v-if="data.page>1" flat label="返回第一頁" :disable="loading" @click="first" /><q-btn flat label="下一頁" :disable="loading||!data.hasMore" @click="next" /></div></template>
  </DataTable>
 </section></div></template>
